CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Sales_vStoreWithAddresses` AS select `s`.`BusinessEntityID` AS `BusinessEntityID`,`s`.`Name` AS `Name`,`at`.`Name` AS `AddressType`,`a`.`AddressLine1` AS `AddressLine1`,`a`.`AddressLine2` AS `AddressLine2`,`a`.`City` AS `City`,`sp`.`Name` AS `StateProvinceName`,`a`.`PostalCode` AS `PostalCode`,`cr`.`Name` AS `CountryRegionName` from (((((`Sales_Store` `s` join `Person_BusinessEntityAddress` `bea` on((`bea`.`BusinessEntityID` = `s`.`BusinessEntityID`))) join `Person_Address` `a` on((`a`.`AddressID` = `bea`.`AddressID`))) join `Person_StateProvince` `sp` on((`sp`.`StateProvinceID` = `a`.`StateProvinceID`))) join `Person_CountryRegion` `cr` on((`cr`.`CountryRegionCode` = `sp`.`CountryRegionCode`))) join `Person_AddressType` `at` on((`at`.`AddressTypeID` = `bea`.`AddressTypeID`)));
